 foreach(listEntities('job') as $candidate){
  if($done+$failed>=$maximum)break;
  $job=transaction(function()use($candidate){$j=entity($candidate['id'],'job',true);if(!$j||!in_array($j['state'],['waiting','delayed','active'],true)||$j['runAt']>now()||($j['state']==='active'&&($j['leaseUntil']??0)>now()))return null;$j['state']='active';$j['leaseUntil']=now()+120000;$j['leaseToken']=uid();$j['attemptsMade']++;return putEntity('job',$j);});
  if(!$job)continue;$error=null;
  try{switch($job['name']){case 'webhook.deliver':deliverWebhook($job['payload']['deliveryId']);break;default:throw new RuntimeException('Unknown job handler.');}}catch(Throwable $e){$error=$e instanceof HttpError?$e->getMessage():'Job delivery failed; check PHP log.';error_log('ZDIS job '.$job['id'].': '.$e->getMessage());}
  transaction(function()use($job,$error){$j=entity($job['id'],'job',true);if(!$j||($j['leaseToken']??null)!==$job['leaseToken'])return;$j['leaseUntil']=null;$j['leaseToken']=null;$j['failedReason']=$error;if($error){$j['state']=$j['attemptsMade']>=5?'failed':'delayed';$j['runAt']=now()+min(3600000,10000*(2**($j['attemptsMade']-1)));}else{$j['state']='completed';$j['finishedOn']=now();}putEntity('job',$j);});
  if($error)$failed++;else $done++;
 }
 return ['completed'=>$done,'failed'=>$failed];
}
